import{_ as o,o as e,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"queueMicrotask","description":"你问得很精准，这里面涉及三个层次： 1. Vue 的微任务 flush 到底做到哪里 Vue 在依赖变更后，会把 组件更新任务 + watch/watchEffect 回调 放到 一个微任务队列 里。 当事件循环进入微任务阶段时： 1. 执行 pre 队列 （默认 watchEf。","frontmatter":{"title":"queueMicrotask","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","异步编程"],"description":"你问得很精准，这里面涉及三个层次： 1. Vue 的微任务 flush 到底做到哪里 Vue 在依赖变更后，会把 组件更新任务 + watch/watchEffect 回调 放到 一个微任务队列 里。 当事件循环进入微任务阶段时： 1. 执行 pre 队列 （默认 watchEf。","sidebarWeight":97,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/11-异步编程/queueMicrotask.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/05-异步编程/queueMicrotask.md","filePath":"posts/JavaScript系统教程/05-异步编程/queueMicrotask.md"}'),a={name:"posts/JavaScript系统教程/05-异步编程/queueMicrotask.md"};function n(i,t,l,c,u,g){return e(),s("div",null,[...t[0]||(t[0]=[r('<div><h1 id="queuemicrotask" tabindex="-1">queueMicrotask <a class="header-anchor" href="#queuemicrotask" aria-label="Permalink to &quot;queueMicrotask&quot;">​</a></h1><blockquote><p>本节目标：理解“queueMicrotask”的核心思路，并能把它用于实际开发或面试表达。 你问得很精准，这里面涉及三个层次：</p></blockquote><p><strong>1. Vue 的微任务 flush 到底做到哪里</strong></p><ul><li>Vue 在依赖变更后，会把<strong>组件更新任务 + watch/watchEffect 回调</strong>放到<strong>一个微任务队列</strong>里。</li><li>当事件循环进入微任务阶段时： <ol><li>执行 <strong>pre 队列</strong>（默认 watchEffect / watch）</li><li>执行 <strong>组件更新队列</strong>（vDOM diff → DOM patch）</li><li>执行 <strong>post 队列</strong>（flush: &#39;post&#39; 的 watchEffect）</li></ol></li><li><strong>结论</strong>：此时 DOM 已经 patch 完成（真实 DOM 树更新了），但<strong>还没进入浏览器的渲染流水线</strong>（样式计算 → 布局 → 绘制 → 合成 → 呈现在屏幕）。</li></ul><p>👉 所以你说的没错：<strong>Vue flush 完成 ≠ 用户已经看到界面</strong>。 DOM 树更新了，但屏幕刷新要等浏览器下一帧。</p><p><strong>2. nextTick、Promise.then 与 rAF 的区别</strong></p><ul><li>**await nextTick()******保证等 Vue 的 flush 全部跑完（包括 patch）后再执行。此时 DOM 是最新的，但屏幕还没画出来。→ 适合：读取/操作最新的 DOM 节点。</li><li><strong>Promise.then</strong>****只是普通微任务，不保证正好在 Vue flush 之后（有可能在 flush 前被调度到）。→ 不可靠，不能代替 nextTick。</li><li><strong>requestAnimationFrame</strong><strong><strong>在浏览器</strong>下一帧渲染前</strong>调用。此时：DOM 已是最新 → 样式/布局计算即将发生。→ 适合：测量尺寸、做动画起点。</li><li><strong>用户真正看到的时机</strong>****是 <strong>浏览器绘制阶段</strong>（在 rAF 回调之后）。</li></ul><p><strong>3. 你提到的 queueMicrotask</strong></p><ul><li>queueMicrotask 是浏览器提供的 <strong>原生 API</strong>，作用类似 Promise.resolve().then(...)，会在<strong>当前宏任务结束后、渲染前</strong>执行。</li><li>它就是“标准化的微任务调度方式”，更语义化，避免滥用 Promise。</li></ul><p>示例： console.log(&quot;sync 1&quot;) queueMicrotask(() =&gt; { console.log(&quot;microtask A&quot;)}) Promise.resolve().then(() =&gt; { console.log(&quot;microtask B&quot;)}) console.log(&quot;sync 2&quot;) // 输出顺序：// sync 1// sync 2// microtask A// microtask B (两者在同一微任务队列，先后看规范和实现)</p><p><strong>4. 串起来的时间线（一次响应式更新 → 用户看到界面）</strong></p><ol><li><strong>同步代码</strong>：修改 state.value</li><li><strong>Vue flush (微任务)</strong>：pre → patch DOM → post → nextTick 回调👉 DOM 树已更新，但用户还没看到</li><li><strong>requestAnimationFrame</strong>：下一帧渲染前执行👉 可安全测量最新 DOM</li><li><strong>浏览器渲染流水线</strong>：样式计算 → 布局 → 绘制 → 合成👉 用户终于看到新界面</li><li><strong>requestIdleCallback</strong>：如果这一帧有空闲，就执行低优先级任务</li></ol><p>✅ 你可以记住一句口诀：</p><ul><li><strong>nextTick 看 DOM</strong></li><li><strong>rAF 看画面</strong></li><li><strong>queueMicrotask = 标准微任务入口</strong></li></ul><p>要不要我帮你画一张「<strong>Vue flush → nextTick → rAF → 用户看到画面</strong>」的时间轴图？（比文字更直观） &gt; 来自 &lt;<a href="https://chatgpt.com/c/68ae5ca2-df20-832e-b3d9-058504d9cae3" target="_blank" rel="noreferrer">https://chatgpt.com/c/68ae5ca2-df20-832e-b3d9-058504d9cae3</a>&gt;</p></div>',1)])])}const f=o(a,[["render",n]]);export{h as __pageData,f as default};
